import React from 'react';

const services = [
  'Rodent control',
  'Termite treatment',
  'Cockroach control',
  'Home protection',
  'Commercial service',
  'Chennai coverage',
];

const ServiceTicker = () => (
  <div className="service-ticker" aria-label="Our pest control services">
    <div className="service-ticker-track">
      {[...services, ...services].map((service, index) => (
        <span key={`${service}-${index}`} className="service-ticker-item">
          <span className="service-ticker-dot" aria-hidden="true" />
          {service}
        </span>
      ))}
    </div>
  </div>
);

export default ServiceTicker;
